ee:message.ee:set-payload:
%dw 2.0
output application/json
var refSetResp = ((payload.compositeResponse filter $.referenceId == "refCaseSet") default [])[0]
var refGetResp = ((payload.compositeResponse filter $.referenceId == "refCaseGet") default [])[0]
---
if((typeOf(refSetResp.body) as String) == "Array" and refSetResp.body[0].errorCode != null) {
  "status": refSetResp.httpStatusCode default 409,
  "code": refSetResp.body[0].errorCode  default "INTERNAL_SERVER_ERROR",
  "message": {
    "message": ""
  },
  "messageServer": refSetResp.body[0].message  default "",
  "cause": [{
            "origin": "salesforce-sapi-services",
            "message": refSetResp.body[0].message default ""
        }]
}
else if((typeOf(refSetResp.body) as String) == "Array" and refGetResp.body[0].errorCode != null) {
  "status": refGetResp.httpStatusCode default 409,
  "code": refGetResp.body[0].errorCode  default "INTERNAL_SERVER_ERROR",
  "message": {
    "message": ""
  },
  "messageServer": refGetResp.body[0].message  default "",
  "cause": [{
            "origin": "salesforce-sapi-services",
            "message": refGetResp.body[0].message default ""
        }]
}
else payload
